// 一条云端下发的 SVM2 信封 + 它的绑定上下文。
// nonce/hwid/version/channel 必须与抓包时一致，否则 PayloadVM 的绑定串校验
// (SHA256(nonce|hwid|wire|version|channel|op)) 不会通过 —— 离线回放靠的就是
// 把当时那一组上下文原样带回来。
struct EmbeddedPayloadEntry {
    int         op;           // 该信封内的 streamOp，必须等于 catalog 里该 wire 的 op
    const char* wire;         // 云端 wire id
    const char* nonce;        // 抓包时的请求 nonce
    const char* hwid;         // 抓包时的 HWID (ANDROID_ID)
    const char* bindVersion;  // 绑定串里用的 version
    const char* bindChannel;  // 绑定串里用的 channel
    const char* envelope;     // "SVM2.<base64>" 原样信封
};

